const titles = {overview:['Admin overview','A live pulse check across your gym operations.'],members:['Members','One directory for every member and lifecycle status.'],joinings:['New joinings','Capture registrations, plans, payments, and assignments.'],plans:['Membership plans','Build the offer catalogue your gym sells every day.'],renewals:['Renewals','Keep upcoming revenue visible and follow-ups accountable.'],expiring:['Expiring soon','Act before a membership reaches its final day.'],expired:['Expired members','Bring lapsed members back with structured follow-up.'],inactive:['Inactive members','Find active members who have stopped showing up.'],discontinued:['Members who left','Preserve history and make rejoining possible.'],payments:['Pending payments','Collect every outstanding rupee with context.'],invoices:['Payments & invoices','A complete ledger for gym and store transactions.'],attendance:['Attendance','Know who is on the floor and when.'],trainers:['Trainers','Manage availability, assignments, and sessions.'],products:['Products','Control the public catalogue and stock movement.'],orders:['Product orders','Track fulfilment from checkout to pickup.'],leads:['Leads & enquiries','Turn interest into trials, joinings, and memberships.'],offers:['Offers & coupons','Manage promotions without losing the audit trail.'],notifications:['Notifications','Send the right reminder to the right audience.'],reports:['Reports & analytics','Turn daily operations into decisions.'],cms:['Website CMS','Manage public website content from one place.'],staff:['Staff management','Set roles and keep the team accountable.'],settings:['Settings','Configure how The Mission Gym operates.']};

function render(){
  const [title, description] = titles[page] || titles.overview;
  const active = Object.prototype.hasOwnProperty.call(layouts,page) ? page : 'overview';
  const sidebar = navGroups.map(group => `<div class="admin-page-nav-group"><strong>${group.label}</strong>${group.items.map(([key,label,icon]) => `<a class="${key===active?'active':''}" href="${href(key)}"><span class="nav-icon">${icon}</span><span>${label}</span></a>`).join('')}</div>`).join('');
  const body = layouts[active] ? layouts[active]() : layouts.overview();
  document.querySelector('#adminPageRoot').innerHTML = `<div class="admin-page-shell"><aside class="admin-page-sidebar"><a class="admin-page-brand" href="index.html"><span class="admin-mark"></span><span>THE MISSION<br>GYM / ADMIN</span></a><div class="admin-page-kicker mono">Workspace</div><nav class="admin-page-nav">${sidebar}</nav><div class="admin-page-user"><div class="admin-page-user-row"><span class="avatar">PS</span><div><strong>Priya Sharma</strong><span>Super admin</span></div></div><a class="admin-page-back" href="index.html">← Back to public site</a></div></aside><main class="admin-page-main"><header class="admin-page-topbar"><div class="admin-page-top-left"><button class="admin-icon admin-page-mobile" id="pageMenu" aria-label="Open dashboard menu">☰</button><div class="admin-page-breadcrumb">Mission Gym / <strong>Admin workspace</strong></div></div><div class="admin-page-actions"><span class="sample-pill"><i></i> Sample data</span><button class="admin-icon" data-action="Notifications" aria-label="Notifications">♢</button><span class="avatar">PS</span></div></header><div class="admin-page-content"><div class="page-heading"><div><span class="mono" style="color:var(--admin-lime)">Friday, 16 October 2026</span><h1>${title}</h1><p>${description}</p></div><div class="page-heading-actions"><button class="admin-btn" data-action="Export report">↓ Export report</button><button class="admin-btn primary" data-action="Add member">+ Add member</button></div></div>${body}</div></main></div><div class="page-toast" id="pageToast"></div>`;
  bind();
}

function bind(){
  const toast = document.querySelector('#pageToast');
  const show = message => { toast.textContent = message; toast.classList.add('show'); clearTimeout(window.pageToastTimer); window.pageToastTimer = setTimeout(() => toast.classList.remove('show'), 2200); };
  document.querySelectorAll('[data-action]').forEach(button => button.addEventListener('click', () => show(`${button.dataset.action} action opened.`)));
  document.querySelectorAll('[data-toggle]').forEach(button => button.addEventListener('click', () => {button.classList.toggle('on'); show(`Setting ${button.classList.contains('on') ? 'enabled' : 'disabled'}.`);}));
  document.querySelector('#pageMenu')?.addEventListener('click', () => document.querySelector('.admin-page-sidebar').classList.toggle('open'));
}
render();
